def my_cad_function(args):
    import cadquery as cq
    from math import pi

    shape = cq.importers.importStep(args["input_file"])   # ALWAYS load the input
    base = shape.val() if hasattr(shape, "val") else shape

    # -------------------- helpers --------------------
    def vfmt(v):
        return f"({v.x:.3f},{v.y:.3f},{v.z:.3f})"

    def bbfmt(bb):
        return (
            f"min=({bb.xmin:.3f},{bb.ymin:.3f},{bb.zmin:.3f}) "
            f"max=({bb.xmax:.3f},{bb.ymax:.3f},{bb.zmax:.3f})"
        )

    # -------------------- numbers explicitly named by the sub-goal --------------------
    bbox_target = (0.0, 300.0, 200.0, 320.0, -445.0, -340.0)
    bore_r = 14.1421
    bore_axis = (1.0, 0.0, 0.0)
    bore_yz = (270.0, -400.0)
    bore_x_span = (100.0, 300.0)
    print(
        "NUMBERS: protected bore r=14.1421 axis||+X center (Y,Z)=(270,-400) X=100..300; "
        "blind opening planes at Y=230 and X=300; required outer bbox X=0..300 Y=200..320 Z=-445..-340"
    )

    sols = base.Solids()
    print(f"INFO: imported solids={len(sols)}")
    if len(sols) < 1:
        print("SELECTED: 0 solids (ERROR)")
        return shape

    solid = sols[0]
    bb0 = solid.BoundingBox()
    print(f"INFO: base bbox {bbfmt(bb0)}")

    faces = solid.Faces()
    edges = solid.Edges()
    print(f"INFO: solid faces={len(faces)} edges={len(edges)}")

    # Resolve key faces by index per instructions (diagnostic / anchoring only)
    key_face_idx = [5, 29, 33, 23, 25, 20, 0, 14, 1, 15, 11]
    for i in key_face_idx:
        try:
            f = faces[i]
            print(
                f"INFO: resolved face #{i} type={f.geomType()} area={f.Area():.3f} "
                f"center={vfmt(f.Center())} normal={vfmt(f.normalAt())} wires={len(f.Wires())}"
            )
        except Exception as e:
            print(f"WARN: could not resolve face #{i}: {e}")

    # -------------------- adjacency: FIX for previous crash --------------------
    # Previous failure root-cause: iterating TopTools_ListOfShape via .cbegin (not available in OCP 7.9.3 Python bindings).
    # Fix: iterate using TopTools_ListIteratorOfListOfShape.
    try:
        from OCP.TopAbs import TopAbs_EDGE, TopAbs_FACE, TopAbs_SHELL
        from OCP.TopExp import TopExp_Explorer
        from OCP.TopExp import TopExp
        from OCP.TopTools import TopTools_IndexedDataMapOfShapeListOfShape, TopTools_ListIteratorOfListOfShape
    except Exception as e:
        print(f"ERROR: could not import required OCP topology tools: {e}")
        return shape

    # Build edge -> faces ancestor map
    edge_face_map = TopTools_IndexedDataMapOfShapeListOfShape()
    try:
        TopExp.MapShapesAndAncestors_s(solid.wrapped, TopAbs_EDGE, TopAbs_FACE, edge_face_map)
        print("INFO: built edge->faces ancestor map")
    except Exception as e:
        print(f"ERROR: MapShapesAndAncestors failed: {e}")
        return shape

    # small model => brute IsSame lookup is fine
    def face_wrapped_to_index(tface):
        for fi, f in enumerate(faces):
            try:
                if f.wrapped.IsSame(tface):
                    return fi
            except Exception:
                pass
        return None

    def adj_faces_of_edge(eidx):
        """Return face indices adjacent to edge index eidx."""
        try:
            ew = edges[eidx].wrapped
        except Exception:
            return []
        if not edge_face_map.Contains(ew):
            return []
        lof = edge_face_map.FindFromKey(ew)
        it = TopTools_ListIteratorOfListOfShape(lof)
        out = []
        while it.More():
            shp = it.Value()
            fi = face_wrapped_to_index(shp)
            if fi is not None:
                out.append(fi)
            it.Next()
        return sorted(set(out))

    # Precompute per-face edge indices and face adjacency
    face_edges_idx = [set() for _ in range(len(faces))]
    face_adj = [set() for _ in range(len(faces))]
    for ei in range(len(edges)):
        af = adj_faces_of_edge(ei)
        if len(af) < 2:
            continue
        for fi in af:
            face_edges_idx[fi].add(ei)
        for a in af:
            for b in af:
                if a != b:
                    face_adj[a].add(b)

    print("SELECTED: adjacency built for all faces (non-manifold edges ignored)")

    # -------------------- protect bore + cavity reached from inner opening loops --------------------
    protected = set()

    # Protect the full 360-degree cylindrical bore wall by its known face index (from geometry index)
    bore_face_idx = 33
    if 0 <= bore_face_idx < len(faces):
        protected.add(bore_face_idx)
    print(f"SELECTED: {1 if bore_face_idx in protected else 0} face for protected full-bore cylindrical wall  idx=[{bore_face_idx}]")

    # Seed faces with inner boundary loops (given)
    opening_seed_faces = [5, 29]
    opening_seed_faces = [i for i in opening_seed_faces if 0 <= i < len(faces)]
    for i in opening_seed_faces:
        protected.add(i)
    print(f"SELECTED: {len(opening_seed_faces)} opening faces with inner loops for inward-protection seed  idx={opening_seed_faces}")

    # Determine inner-loop edges robustly from those faces (and compare against expected edge indices)
    def global_edge_indices_of_edges(edge_list):
        out = []
        for e in edge_list:
            for gi, ge in enumerate(edges):
                try:
                    if ge.wrapped.IsSame(e.wrapped):
                        out.append(gi)
                        break
                except Exception:
                    pass
        return sorted(set(out))

    seed_edge_idx = []
    for fi in opening_seed_faces:
        wf = faces[fi].Wires()
        inner_edges = []
        if len(wf) > 1:
            for w in wf[1:]:
                inner_edges.extend(w.Edges())
        gei = global_edge_indices_of_edges(inner_edges)
        seed_edge_idx.extend(gei)
        print(f"INFO: face #{fi} inner-loop edges (derived) count={len(gei)} idx={gei}")

    seed_edge_idx = sorted(set(seed_edge_idx))
    print(f"SELECTED: {len(seed_edge_idx)} edges from inner loops for inward-protection traversal seed")

    # Flood-fill inward from those loop edges.
    # Guard: do NOT allow the fill to jump onto the huge exterior cap planes (area threshold),
    # which would accidentally protect most of the outer shell.
    exterior_plane_area_guard = 15000.0

    q = []
    for ei in seed_edge_idx:
        for afi in adj_faces_of_edge(ei):
            if afi not in protected:
                protected.add(afi)
                q.append(afi)

    while q:
        fi = q.pop(0)
        for ei in list(face_edges_idx[fi]):
            for nfi in adj_faces_of_edge(ei):
                if nfi in protected:
                    continue
                try:
                    nf = faces[nfi]
                    if nf.geomType() == "PLANE" and nf.Area() > exterior_plane_area_guard and len(nf.Wires()) == 1:
                        continue
                except Exception:
                    pass
                protected.add(nfi)
                q.append(nfi)

    print(f"SELECTED: {len(protected)} faces protected (bore + inward cavity flood) idx={sorted(list(protected))}")

    # -------------------- classify exterior treatments by adjacency (not by type alone) --------------------
    try:
        from OCP.BRepAdaptor import BRepAdaptor_Surface
        from OCP.GeomAbs import (
            GeomAbs_Plane,
            GeomAbs_Cylinder,
            GeomAbs_Cone,
            GeomAbs_Sphere,
            GeomAbs_BSplineSurface,
        )
        from OCP.BRep import BRep_Tool
    except Exception as e:
        print(f"ERROR: could not import OCP surface adapters: {e}")
        return shape

    def surf_metrics(f):
        """Return (geomAbsType, radius, sweep_deg) for cylinders; others return (type, None, None)."""
        try:
            ad = BRepAdaptor_Surface(f.wrapped, True)
            st = ad.GetType()
            if st == GeomAbs_Cylinder:
                r = float(ad.Cylinder().Radius())
                u1 = float(ad.FirstUParameter())
                u2 = float(ad.LastUParameter())
                sweep = abs(u2 - u1) * 180.0 / pi
                # normalize very near 360
                if sweep > 350.0:
                    sweep = 360.0
                return st, r, sweep
            return st, None, None
        except Exception:
            return None, None, None

    # Candidate signature radii & planar bevel normals
    cand_radii = [30.0, 35.0, 10.0, 5.0, 2.5]
    bevel_normals = [
        cq.Vector(0, -0.707, -0.707),
        cq.Vector(0, -0.707, 0.707),
        cq.Vector(0.707, 0, -0.707),
    ]

    def near(a, b, tol):
        return abs(a - b) <= tol

    def unit(v):
        try:
            if v.Length <= 0:
                return v
            return v.multiply(1.0 / v.Length)
        except Exception:
            return v

    def dot(a, b):
        return a.x * b.x + a.y * b.y + a.z * b.z

    # First, build a broad candidate set (potential blends/bevels/corner patches)
    candidates = set()
    cand_debug = []
    for i, f in enumerate(faces):
        if i in protected:
            continue
        gt = f.geomType()
        try:
            n = unit(f.normalAt())
        except Exception:
            n = cq.Vector(0, 0, 0)

        st, r, sweep = surf_metrics(f)

        is_candidate = False
        reason = ""

        # Cylindrical blend candidates: partial sweep, radii in measured signatures
        if gt == "CYLINDER" and r is not None and sweep is not None:
            if sweep < 170.0 and any(near(r, rr, 0.2) for rr in cand_radii):
                is_candidate = True
                reason = f"CYL r={r:.3f} sweep={sweep:.1f}"

        # Cones: listed exterior cones are candidates (but still need adjacency confirmation)
        if gt == "CONE":
            is_candidate = True
            reason = "CONE"

        # Sphere + BSPLINE: potential trihedral corner patches
        if gt in ("SPHERE", "BSPLINE"):
            is_candidate = True
            reason = gt

        # Planar bevel strips: oblique normals and small-ish area
        if gt == "PLANE":
            try:
                # close to any of the oblique normals (either direction)
                for bn in bevel_normals:
                    bn_u = unit(bn)
                    if abs(dot(n, bn_u)) > 0.995:
                        if f.Area() < 3000.0:
                            is_candidate = True
                            reason = f"PLANE bevel-like n~{vfmt(bn_u)}"
                            break
            except Exception:
                pass

        if is_candidate:
            candidates.add(i)
            cand_debug.append((i, reason, gt, f.Area()))

    print(f"SELECTED: {len(candidates)} faces as broad treatment candidates (pre adjacency-confirmation)")
    if cand_debug:
        print("INFO: candidate list (idx, reason, type, area):")
        for i, reason, gt, a in sorted(cand_debug, key=lambda x: x[0]):
            print(f"  cand face #{i}: {reason} type={gt} area={a:.3f}")

    # Now confirm a face is a treatment ONLY if it bridges 2 or 3 exterior support surfaces
    # and the supports are NOT protected.
    treatment_faces = set()
    support_faces = set()

    def is_support_face(fi):
        if fi in protected:
            return False
        f = faces[fi]
        gt = f.geomType()
        if gt == "PLANE":
            return True
        if gt in ("CYLINDER", "CONE"):
            st, r, sweep = surf_metrics(f)
            # treat large wraps as supports (boss/end surfaces), but NOT small corner blends
            if sweep is None:
                return False
            return sweep >= 170.0
        return False

    for ci in sorted(list(candidates)):
        neigh = sorted(list(face_adj[ci]))
        # supports are exterior (not protected) and not themselves in candidates
        supports = [ni for ni in neigh if (ni not in protected) and (ni not in candidates) and is_support_face(ni)]
        supports = sorted(set(supports))
        if len(supports) in (2, 3):
            treatment_faces.add(ci)
            for si in supports:
                support_faces.add(si)

    print(f"SELECTED: {len(treatment_faces)} faces CONFIRMED as exterior treatments by adjacency bridging 2-3 supports idx={sorted(list(treatment_faces))}")
    print(f"SELECTED: {len(support_faces)} unique support faces adjacent to confirmed treatments idx={sorted(list(support_faces))}")

    if len(treatment_faces) == 0 or len(support_faces) == 0:
        print("ERROR: classification found 0 confirmed treatments or 0 supports; cannot proceed with reconstruction without risk. Returning input unchanged.")
        return shape

    # -------------------- extend support surfaces, remove treatments, sew --------------------
    try:
        from OCP.BRepBuilderAPI import BRepBuilderAPI_MakeFace, BRepBuilderAPI_Sewing, BRepBuilderAPI_MakeSolid
    except Exception as e:
        print(f"ERROR: could not import sewing tools: {e}")
        return shape

    patch_faces_wrapped = []
    rebuilt_supports = set()

    for si in sorted(list(support_faces)):
        if si in protected:
            continue
        sf = faces[si]
        if len(sf.Wires()) > 1:
            print(f"INFO: support face idx={si} has inner wires (loops); not reconstructing to preserve openings")
            continue

        try:
            ad = BRepAdaptor_Surface(sf.wrapped, True)
            st = ad.GetType()

            # Use adaptor bounds to avoid BRepTools UV API differences
            u1 = float(ad.FirstUParameter())
            u2 = float(ad.LastUParameter())
            v1 = float(ad.FirstVParameter())
            v2 = float(ad.LastVParameter())

            # Extension amounts in parameter space
            if st == GeomAbs_Plane:
                du, dv = 200.0, 200.0
            elif st == GeomAbs_Cylinder:
                du, dv = 0.75, 200.0
            elif st == GeomAbs_Cone:
                du, dv = 0.75, 200.0
            else:
                print(f"INFO: support face idx={si} geomAbsType={st} not reconstructed")
                continue

            surf = BRep_Tool.Surface_s(sf.wrapped)
            mf = BRepBuilderAPI_MakeFace(surf, u1 - du, u2 + du, v1 - dv, v2 + dv, 1e-7)
            if not mf.IsDone():
                print(f"WARN: MakeFace failed for support face idx={si}; keeping original")
                continue

            newf = mf.Face()
            patch_faces_wrapped.append(newf)
            rebuilt_supports.add(si)

            print(
                f"SELECTED: rebuilt support face idx={si} type={sf.geomType()} "
                f"U=({u1:.6f},{u2:.6f}) V=({v1:.6f},{v2:.6f}) ext=(du={du},dv={dv})"
            )
        except Exception as e:
            print(f"WARN: could not rebuild support face idx={si}: {e}")

    print(f"SELECTED: {len(rebuilt_supports)} support faces successfully rebuilt idx={sorted(list(rebuilt_supports))}")
    print(f"SELECTED: {len(patch_faces_wrapped)} extended support face patches to add")

    if len(patch_faces_wrapped) == 0:
        print("ERROR: 0 support patches created; cannot perform shell replacement without opening the model. Returning input unchanged.")
        return shape

    # Keep all unaffected original faces, remove confirmed treatments and the supports being rebuilt
    removed_all = set(treatment_faces) | set(rebuilt_supports)
    keep_wrapped = []
    for i, f in enumerate(faces):
        if i in protected:
            keep_wrapped.append(f.wrapped)
            continue
        if i in removed_all:
            continue
        keep_wrapped.append(f.wrapped)

    print(f"SELECTED: {len(keep_wrapped)} original faces kept for sewing")
    print(f"SELECTED: {len(removed_all)} original faces removed (treatments + old trims of rebuilt supports) idx={sorted(list(removed_all))}")

    # Sew with cutting enabled so extended faces are trimmed by their intersections.
    try:
        sew = BRepBuilderAPI_Sewing(1e-6, True, True, True, False)
        for fw in keep_wrapped:
            sew.Add(fw)
        for pf in patch_faces_wrapped:
            sew.Add(pf)
        sew.Perform()
        sewed = sew.SewedShape()
    except Exception as e:
        print(f"ERROR: sewing failed: {e}")
        return shape

    # Extract shells
    shells = []
    ex = TopExp_Explorer(sewed, TopAbs_SHELL)
    while ex.More():
        shells.append(ex.Current())
        ex.Next()

    print(f"INFO: sewing produced shells={len(shells)}")
    if len(shells) != 1:
        print("ERROR: sewing did not produce exactly 1 shell; returning input unchanged")
        return shape

    try:
        ms = BRepBuilderAPI_MakeSolid()
        ms.Add(shells[0])
        if not ms.IsDone():
            print("ERROR: MakeSolid not done; returning input unchanged")
            return shape
        out = cq.Shape.cast(ms.Solid())
    except Exception as e:
        print(f"ERROR: MakeSolid failed: {e}")
        return shape

    # -------------------- validate against required envelope --------------------
    bb1 = out.BoundingBox()
    print(f"CHECK: output bbox {bbfmt(bb1)}")

    deltas = [
        abs(bb1.xmin - bbox_target[0]),
        abs(bb1.xmax - bbox_target[1]),
        abs(bb1.ymin - bbox_target[2]),
        abs(bb1.ymax - bbox_target[3]),
        abs(bb1.zmin - bbox_target[4]),
        abs(bb1.zmax - bbox_target[5]),
    ]
    db = max(deltas)
    print(f"VERIFY: bbox max-delta vs required envelope = {db:.6f} mm")

    # Diagnostic only: quantify how much changed (booleans used only as measurement tools)
    try:
        removed_dbg = solid.cut(out)
        added_dbg = out.cut(solid)
        print(f"CHECK: diagnostic removed volume={removed_dbg.Volume():.3f} mm^3")
        print(f"CHECK: diagnostic added volume={added_dbg.Volume():.3f} mm^3")
        if removed_dbg.Volume() > 1e-6:
            rbb = removed_dbg.BoundingBox()
            print(f"CHECK: diagnostic removed bbox {bbfmt(rbb)}")
        if added_dbg.Volume() > 1e-6:
            abb = added_dbg.BoundingBox()
            print(f"CHECK: diagnostic added bbox {bbfmt(abb)}")
    except Exception as e:
        print(f"WARN: diagnostic added/removed computation failed: {e}")

    # Must not change outer envelope
    if db > 0.05:
        print("ERROR: envelope changed beyond tolerance; rejecting reconstruction and returning input unchanged.")
        return shape

    try:
        print(f"CHECK: output valid={out.isValid()}")
    except Exception as e:
        print(f"WARN: could not validate output isValid(): {e}")

    try:
        osols = out.Solids()
        print(f"CHECK: output solids={len(osols)}")
        if len(osols) != 1:
            print("ERROR: output solid count != 1; returning input unchanged")
            return shape
    except Exception as e:
        print(f"WARN: could not count output solids: {e}")

    # Multi-solid safety (though input is single-solid)
    if len(sols) == 1:
        return out

    comp = cq.Compound.makeCompound([s for i, s in enumerate(sols) if i != 0] + [out])
    return comp
